<?php
namespace App\Services;use App\Models\CommitteeElection;use Illuminate\Validation\ValidationException;
class CommitteeElectionResultService {public function calculate(CommitteeElection $e):array {$ballots=$e->ballots()->count();$voters=$e->voters()->where('has_voted',true)->count();if($ballots!==$voters)throw ValidationException::withMessages(['integrity'=>'Se detectó una inconsistencia de integridad entre sufragantes y ballots.']);$rows=$e->candidates()->withCount('selections')->orderByDesc('selections_count')->get();$results=$rows->map(fn($c)=>['id'=>$c->id,'name'=>$c->name,'votes'=>$c->selections_count,'percentage'=>$ballots?round($c->selections_count/$ballots*100,2):0])->all();$digest=hash('sha256',json_encode([$e->public_uuid,$ballots,$results,$e->closed_at?->toIso8601String()],JSON_UNESCAPED_UNICODE));return compact('ballots','voters','results','digest');}}
